RT::Cell_handle_base ch = c;
for (int i = 0; i < 4; ++i) {
    Weighted_point wp = ch->vertex(i)->point();
    points[i] = lifted_point(wp.x(), wp.y(), wp.z(), wp.weight());
}

HyperPlane hp(points[0], points[1], points[2], points[3]);
double a = hp.coefficient(0);
double b = hp.coefficient(1);
double c_coeff = hp.coefficient(2);
double d = hp.coefficient(3);
double e = hp.coefficient(4);

double norm_sq = a * a + b * b + c_coeff * c_coeff;
if (norm_sq < 1e-18) {
    return Vector(0, 0, 0);
}

double inv_norm = 1.0 / std::sqrt(norm_sq);
double vx = a * inv_norm;
double vy = b * inv_norm;
double vz = c_coeff * inv_norm;

return Vector(vx / time, vy / time, vz / time);

